#!/usr/bin/env node
/** Installs git pre-commit hook to run version tracking when changes are staged. */
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, '..');
const HOOKS_DIR = path.join(ROOT, '.git/hooks');
const HOOK_PATH = path.join(HOOKS_DIR, 'pre-commit');

const HOOK = `#!/bin/sh
# Auto-generated by scripts/install-git-hooks.mjs
if git diff --cached --quiet; then
  exit 0
fi
node scripts/version-track.mjs
git add .idrac-version-state.json package.json apps/web/package.json apps/api/package.json apps/console-gw/package.json packages/shared/package.json packages/shared/src/version.ts packages/db/package.json packages/adapters/package.json packages/ui/package.json 2>/dev/null || true
exit 0
`;

if (!fs.existsSync(HOOKS_DIR)) {
  console.log('[install-git-hooks] No .git/hooks directory — skipping');
  process.exit(0);
}

fs.writeFileSync(HOOK_PATH, HOOK, { mode: 0o755 });
console.log('[install-git-hooks] pre-commit hook installed');
